function QuestionnaireChoice({
  children,
  className,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Choice>) {
  return (
    <QuestionnairePrimitive.Choice
      data-slot="questionnaire-choice"
      className={cn(
        "group/questionnaire-choice relative flex min-h-11 cursor-pointer items-start gap-2.5 rounded-[var(--r-md)] border border-[var(--control-border)] bg-[var(--control-background)] px-3 py-2.5 text-start text-sm text-[var(--control-foreground)] transition-colors outline-none select-none hover:bg-[var(--surface-muted-background)] active:border-[var(--control-border-active)] active:bg-[var(--control-background-active)] has-[>input:focus-visible]:border-transparent has-[>input:focus-visible]:[box-shadow:var(--shadow-keyboard-focus)] data-invalid:border-[var(--control-invalid-border)] data-checked:border-[var(--control-focus-border)] data-checked:bg-[var(--control-selected-soft-background)] data-checked:active:border-[var(--control-focus-border)] data-checked:active:bg-[var(--control-selected-soft-background)]",
        "data-disabled:pointer-events-none data-disabled:cursor-not-allowed data-disabled:bg-[var(--control-disabled-background)] data-disabled:text-[var(--control-disabled-foreground)]",
        className
      )}
      {...props}
    >
      <QuestionnairePrimitive.ChoiceInput
        data-slot="questionnaire-choice-input"
        className="absolute inset-0 z-10 size-full cursor-pointer opacity-0"
      />
      <span
        aria-hidden="true"
        data-slot="questionnaire-choice-indicator"
        className="pointer-events-none relative flex size-4 shrink-0 translate-y-[--spacing(0.45)] items-center justify-center rounded-[var(--r-xs)] border border-[var(--control-border)] bg-[var(--control-background)] group-has-data-[slot=questionnaire-choice-description]/questionnaire-choice:translate-y-0.5 group-data-[type=radio]/questionnaire-choice:rounded-full group-data-checked/questionnaire-choice:border-[var(--control-selected-background)] group-data-checked/questionnaire-choice:bg-[var(--control-selected-background)] group-data-checked/questionnaire-choice:text-[var(--control-selected-foreground)]"
      >
        <span
          data-slot="questionnaire-choice-indicator-dot"
          className="hidden size-2 rounded-full bg-[var(--control-selected-foreground)] group-data-[type=checkbox]/questionnaire-choice:hidden group-data-checked/questionnaire-choice:block"
        />
        <CheckIcon
          data-slot="questionnaire-choice-indicator-check"
          className="hidden size-3.5 group-data-[type=radio]/questionnaire-choice:hidden group-data-checked/questionnaire-choice:block"
        />
      </span>
      <QuestionnairePrimitive.ChoiceLabel
        data-slot="questionnaire-choice-label"
        className="typo-b9r flex min-w-0 flex-1 flex-col gap-0.5"
      >
        {children}
      </QuestionnairePrimitive.ChoiceLabel>
      <QuestionnairePrimitive.ChoiceShortcut
        data-slot="questionnaire-choice-shortcut"
        className="pointer-events-none ms-auto hidden size-5 shrink-0 translate-y-[--spacing(0.45)] items-center justify-center rounded-[var(--r-xs)] border border-[var(--control-border)] bg-[var(--control-background)] font-mono text-[length:var(--text-label-3)] leading-[var(--leading-label-3)] font-medium text-[var(--surface-muted-foreground)] group-has-data-[slot=questionnaire-choice-description]/questionnaire-choice:translate-y-0.5 group-data-[shortcut]/questionnaire-choice:inline-flex"
      />
    </QuestionnairePrimitive.Choice>
  )
}

